traces.query:
PREFIX net: <http://example.org/network#>
SELECT ?alarm ?label
WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice ?dev ;
         rdfs:label ?label .
  ?dev a net:NetworkDevice ;
       rdfs:label "Edge Firewall FW1" .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(?alarm) AS ?criticalAlarmCount)
WHERE {
  ?alarm a net:Alarm ;
         net:hasSeverity "CRITICAL" .
}

PREFIX net: <http://example.org/network#>
SELECT ?alarm ?label WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice net:Router_Core ;
         rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>
SELECT ?severity WHERE {
  net:Alarm_PacketDrop net:hasSeverity ?severity .
}

PREFIX net: <http://example.org/network#>
SELECT ?device (COUNT(?alarm) AS ?alarmCount)
WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice ?device .
}
GROUP BY ?device
ORDER BY DESC(?alarmCount)
LIMIT 1

PREFIX net: <http://example.org/network#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?alarm ?time
WHERE {
  ?alarm a net:Alarm ;
         net:triggeredAt ?time .
}
ORDER BY ?time
LIMIT 1

PREFIX net: <http://example.org/network#>
SELECT ?mitreId WHERE {
  net:Incident_DDoS net:classifiedAs ?ap .
  ?ap net:mitreId ?mitreId .
}

PREFIX net: <http://example.org/network#>

SELECT ?deviceType
WHERE {
  net:Server_Web net:deviceType ?deviceType .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(?alarm) AS ?alarmCount)
WHERE {
  net:Incident_DDoS net:composedOf ?alarm .
}

PREFIX net: <http://example.org/network#>
SELECT ?alarm WHERE {
  ?alarm a net:Alarm ;
         net:hasSeverity "HIGH" .
}

PREFIX net: <http://example.org/network#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?alarm ?time
WHERE {
  ?alarm a net:Alarm ;
         net:triggeredAt ?time .
  FILTER ( ?time > "2026-06-02T14:01:00"^^xsd:dateTime )
}

PREFIX net: <http://example.org/network#>
SELECT ?rootCauseAlarm WHERE {
  net:Incident_DDoS net:composedOf ?alarm .
  ?alarm net:causallyLinkedTo* ?rootCauseAlarm .
  FILTER NOT EXISTS { ?parent net:causallyLinkedTo ?rootCauseAlarm }
}

PREFIX net: <http://example.org/network#>
SELECT ?rootCause WHERE {
  net:Alarm_WebTimeout (net:causallyLinkedTo)* ?rootCause .
  FILTER NOT EXISTS { ?rootCause net:causallyLinkedTo ?any . }
}

PREFIX net: <http://example.org/network#>
SELECT ?causeLabel WHERE {
  net:Alarm_Latency net:causallyLinkedTo ?cause .
  ?cause rdfs:label ?causeLabel .
}

PREFIX net: <http://example.org/network#>
SELECT ?alarm ?label WHERE {
  ?alarm a net:Alarm ;
         rdfs:label ?label .
  <http://example.org/network#Alarm_FirewallSpike> net:causallyLinkedTo+ ?alarm .
}

PREFIX net: <http://example.org/network#>
SELECT ?intermediateAlarm WHERE {
  net:Alarm_FirewallSpike net:causallyLinkedTo ?intermediateAlarm .
  ?intermediateAlarm net:causallyLinkedTo* net:Alarm_WebTimeout .
  FILTER(?intermediateAlarm != net:Alarm_FirewallSpike && ?intermediateAlarm != net:Alarm_WebTimeout)
}

PREFIX net: <http://example.org/network#>
ASK {
  net:Alarm_CPU net:causallyLinkedTo+ net:Alarm_WebTimeout .
}

PREFIX net: <http://example.org/network#>

SELECT ?intermediate WHERE {
  net:Alarm_Latency net:causallyLinkedTo+ ?intermediate .
  FILTER(?intermediate = net:Alarm_WebTimeout)
}

PREFIX net: <http://example.org/network#>
SELECT ?rootAlarm ?device WHERE {
  ?rootAlarm a net:Alarm .
  FILTER NOT EXISTS { ?cause net:causallyLinkedTo ?rootAlarm . }
  ?rootAlarm net:affectsDevice ?device .
}

PREFIX net: <http://example.org/network#>
SELECT ?cause ?effect WHERE {
  VALUES ?a { net:Alarm_Latency net:Alarm_PacketDrop }
  ?cause net:causallyLinkedTo ?effect .
  FILTER(?cause = net:Alarm_Latency && ?effect = net:Alarm_PacketDrop ||
         ?cause = net:Alarm_PacketDrop && ?effect = net:Alarm_Latency)
}

PREFIX net: <http://example.org/network#>

SELECT ?alarm
WHERE {
  net:Alarm_PacketDrop net:correlatedWith ?alarm .
  FILTER NOT EXISTS { net:Alarm_PacketDrop net:causallyLinkedTo ?alarm }
}

PREFIX net: <http://example.org/network#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?device ?deviceLabel (COUNT(DISTINCT ?otherAlarm) AS ?cnt) WHERE {
  ?rootAlarm a net:Alarm ;
             net:affectsDevice ?device ;
             rdfs:label ?rootLabel .
  ?rootAlarm (net:causallyLinkedTo)+ ?otherAlarm .
  ?otherAlarm net:affectsDevice ?otherDevice .
  FILTER(?otherDevice != ?device)
  FILTER NOT EXISTS {
    ?otherAlarm (net:causallyLinkedTo)+ ?rootAlarm .
  }
  ?device rdfs:label ?deviceLabel .
}
GROUP BY ?device ?deviceLabel
ORDER BY DESC(?cnt)
LIMIT 1

PREFIX net: <http://example.org/network#>
SELECT ?downstreamAlarm ?label WHERE {
  net:Alarm_FirewallSpike net:causallyLinkedTo+ ?downstreamAlarm .
  ?downstreamAlarm rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>

SELECT ?downstreamAlarm ?downstreamAlarmLabel WHERE {
  <http://example.org/network#Alarm_CPU> net:causallyLinkedTo+ ?downstreamAlarm .
  ?downstreamAlarm rdfs:label ?downstreamAlarmLabel .
}

PREFIX net: <http://example.org/network#>

SELECT (COUNT(DISTINCT ?downstream) AS ?preventedAlarms)
WHERE {
  net:Alarm_PacketDrop (net:causallyLinkedTo)+ ?downstream .
}

PREFIX net: <http://example.org/network#>

SELECT ?remainingAlarm ?type ?severity ?time
WHERE {
  net:Incident_DDoS net:composedOf ?remainingAlarm .
  ?remainingAlarm net:alarmType ?type ;
                 net:hasSeverity ?severity ;
                 net:triggeredAt ?time .
  FILTER NOT EXISTS {
    net:Alarm_CPU net:causallyLinkedTo ?remainingAlarm .
  }
}

PREFIX net: <http://example.org/network#>

ASK {
  net:Alarm_Latency net:causallyLinkedTo+ net:Alarm_WebTimeout .
}
